/* @lc app=leetcode id=4022 lang=kotlin */ class Solution { fun kthDigit(k: Long): Int = if (k <= 9) k.toInt() else generateSequence(2 to k - 9) { (L, rem) -> (9L * "1".padEnd(L - 1, '0').toLong() * 10 * L).let { tot -> if (rem > tot) (L + 1) to rem - tot else null } }.last().let { (L, rem) -> "1".padEnd(L - 1, '0').toLong().let { b0 -> (b0 + (rem - 1) / (10 * L)).let { b -> ((rem - 1) % (10 * L)).let { w -> (w / L).let { idx -> (10 * b + (if (b % 2 == 0L) idx else 9 - idx)).toString()[(w % L).toInt()] - '0' } } } } } }